/* Reduced from PR optimization/5076, PR optimization/2847 */

void abort(void);

static int count = 0;

static void inc(void) { count++; }

int main(void) {
  int iNbr = 1;
  int test = 0;
  while (test == 0) {
    inc();
    if (iNbr == 0)
      break;
    else {
      inc();
      iNbr--;
    }
    test = 1;
  }
  if (count != 2)
    abort();
  return 0;
}


